# Run a coverage-guided fuzzer against a persistent directory of seed inputs.
# The C harness receives each generated byte sequence; libFuzzer mutates inputs
# and retains examples that reach new paths. Corpus files survive repeated runs;
# crash artifacts preserve reproducible failures. A nonzero fuzzer status is
# propagated so CI does not mistake a crash for a successful test run.

"""Seed libFuzzer from bundled samples; retain its corpus, log, and crash artifacts."""
import argparse
from pathlib import Path
import shutil
import subprocess
from fixtures import fuzz_seeds

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('binary', type=Path)
parser.add_argument('--runs', type=int, default=1000)
args = parser.parse_args()
root = Path(__file__).resolve().parents[1]
binary = args.binary.resolve()
work = binary.parent
corpus = work / 'corpus'
# exist_ok preserves discoveries from earlier runs rather than clearing them.
corpus.mkdir(parents=True, exist_ok=True)
artifacts = work / 'artifacts'
artifacts.mkdir(exist_ok=True)
for name in ('testexecutable.exe', 'testelf', 'testmach'):
    shutil.copyfile(root / name, corpus / name)
for sample in sorted(root.glob('hello-*')):
    shutil.copyfile(sample, corpus / sample.name)
for name, data in fuzz_seeds().items():
    (corpus / name).write_bytes(data)
log = work / 'fuzz.log'
# Combine stdout/stderr into one diagnostic log. The limits bound each input's
# size and execution time; --runs chooses how many mutations libFuzzer attempts.
with log.open('w') as output:
    result = subprocess.run([str(binary), str(corpus), f'-runs={args.runs}',
                             '-max_len=1048576', '-timeout=5',
                             f'-artifact_prefix={artifacts}/'],
                            stdout=output, stderr=subprocess.STDOUT)
print('\n'.join(log.read_text(errors='replace').splitlines()[-12:]))
print(f'Fuzzer log: {log}')
raise SystemExit(result.returncode)
